function f({registerIndicator:h,nulls:c}){const a=(o,l)=>{const r=new Array(o.length).fill(NaN);let i=0;for(let t=0;t<o.length;t++){i+=o[t],t>=l&&(i-=o[t-l]);const n=Math.min(t+1,l);r[t]=n>0?i/n:o[t]}return r};h({id:"oa-vo",name:"Volume Oscillator (VO)",category:"Volume",placement:"pane",inputs:[{key:"shortPeriod",type:"number",label:"Short Period",default:5,min:1,max:50,step:1,tooltip:"Period for short-term volume moving average"},{key:"longPeriod",type:"number",label:"Long Period",default:10,min:2,max:100,step:1,tooltip:"Period for long-term volume moving average"},{key:"signalPeriod",type:"number",label:"Signal Period",default:10,min:1,max:50,step:1,tooltip:"Period for signal line moving average"}],plots:[{key:"vo",type:"line",title:"Volume Oscillator",style:{color:"#ffeb3b",lineWidth:2}},{key:"signal",type:"line",title:"Signal Line",style:{color:"#2196f3",lineWidth:2}}],calc(o,l){const r=Math.max(1,Math.floor(Number(l.shortPeriod)||5)),i=Math.max(2,Math.floor(Number(l.longPeriod)||10)),t=Math.max(1,Math.floor(Number(l.signalPeriod)||10)),n=new Array(o.length);for(let e=0;e<o.length;e++){const u=Number.isFinite(o[e].volume)?o[e].volume:0;n[e]=Math.max(u,1)}const s=a(n,r),m=a(n,i),g=new Array(o.length).fill(NaN);for(let e=0;e<o.length;e++)g[e]=m[e]>0?(s[e]-m[e])/m[e]*100:0;const d=a(g,t);return{vo:c(g),signal:c(d)}}})}export{f as default};
